fn length(s: &String) -> usize {
    s.len()
}

fn main() {
    let s = String::from("abc");
    let n = length(&s);
    println!("{s} {n}");
}

fn main() {
    let mut s = String::from("hi");
    let r1 = &mut s;
    let r2 = &mut s;
    r1.push('a');
    r2.push('b');
}

fn main() {
    let mut s = String::from("ab");
    let r = &s;
    println!("{r}");
    s.push('c');
    println!("{s}");
}

fn exclaim(s: &mut String) {
    s.push('!');
}

fn main() {
    let mut a = String::from("hi");
    exclaim(&mut a);
    exclaim(&mut a);
    println!("{a} {}", a.len());
}

fn main() {
    let mut s = String::from("x");
    let a = &s;
    let b = &s;
    println!("{a}{b}");
    let c = &mut s;
    c.push('y');
    println!("{c}");
    println!("{s}");
}
